import json, re
c = json.load(open("build/Build/Products/Debug/Frame Job Debug.app/Contents/Resources/agent-catalog.json"))
print(type(c), list(c.keys())[:10] if isinstance(c, dict) else len(c))
tools = c if isinstance(c, list) else c.get("tools", c)
for t in tools:
    if t.get("name") == "set_video":
        print(list(t.keys()))
        s = json.dumps(t)
        for k in ("filters", "reflection", "spotlight"):
            for m in list(re.finditer(k, s))[:5]:
                print(k, m.start(), s[max(0, m.start() - 60):m.start() + 300].replace("\\n", " "))

